import type { ComponentProps } from "react";
import { FooterStacked as Block } from "./footer";

export function FooterStacked(props: ComponentProps<typeof Block>) {
  return <Block {...props} />;
}

import type { ComponentProps, ReactNode } from "react";
import { ArrowUpRight } from "lucide-react";
import { cn } from "cn";
import { GitHubDark } from "@ridemountainpig/svgl-react";
import { Badge } from "../components/badge";
import { Card } from "../components/card";

interface FooterProps extends ComponentProps<"footer"> {
  brand?: string;
  homeHref?: string;
  description?: string;
  groups?: { title: string; links: { label: string; href: string }[] }[];
  githubHref?: string;
  copyright?: string;
  callout?: { title: string; description: string; label: string; href: string };
  action?: ReactNode;
}

function FooterLayout({ layout, brand = "Hangry UI", homeHref = "/", description = "Thoughtful components. Less setup. More time to build.", groups = [{ title: "Explore", links: [{ label: "Components", href: "/components" }, { label: "Blocks", href: "/blocks" }] }, { title: "Resources", links: [{ label: "Button", href: "/components/button" }, { label: "Tabs", href: "/components/tabs" }, { label: "Table", href: "/components/table" }] }], githubHref = "https://github.com/ascx-studio/ui", copyright = `© ${new Date().getFullYear()} Hangry UI`, callout, action, className, children, ...props }: FooterProps & { layout: "columns" | "minimal" | "stacked" }) {
  return (
    <footer {...props} data-slot="footer" data-layout={layout} className={cn("w-full border border-border bg-background text-foreground", className)}>
      {callout && <div className="border-b border-border p-6 sm:p-8">
        <Card title={callout.title} description={callout.description} className="max-w-none!" footer={action ?? <a href={callout.href} className="inline-flex min-h-10 items-center gap-2 text-sm font-medium hover:underline focus-visible:outline-2 focus-visible:outline-ring">{callout.label}<ArrowUpRight size={16} aria-hidden="true" /></a>} />
      </div>}
      <div className={cn("gap-10 p-6 sm:p-8", layout === "columns" ? "grid md:grid-cols-[1.5fr_2fr]" : layout === "minimal" ? "flex flex-wrap items-center justify-between" : "flex flex-col items-center text-center")}>
        <div>
          <a href={homeHref} className="text-xl font-semibold focus-visible:outline-2 focus-visible:outline-ring">{brand}</a>
          {layout !== "minimal" && <p className="mt-3 max-w-sm text-sm leading-6 text-muted-foreground">{description}</p>}
          {layout !== "minimal" && <div className="mt-4"><Badge variant="success">Open source</Badge></div>}
          {children}
        </div>
        <div className={cn(layout === "minimal" ? "flex flex-wrap gap-6" : "grid grid-cols-2 gap-8")}>
          {groups.map(group => <nav key={group.title} aria-label={group.title}>
            {layout !== "minimal" && <h3 className="mb-4 text-sm font-semibold">{group.title}</h3>}
            <ul className={layout === "minimal" ? "flex flex-wrap gap-4" : "space-y-3"}>
              {group.links.map(link => <li key={link.href}><a href={link.href} className="text-sm text-muted-foreground hover:text-foreground focus-visible:outline-2 focus-visible:outline-ring">{link.label}</a></li>)}
            </ul>
          </nav>)}
        </div>
      </div>
      <div className="flex flex-wrap items-center justify-between gap-4 border-t border-border px-6 py-4 text-xs text-muted-foreground sm:px-8">
        <span>{copyright}</span>
        {githubHref && <a href={githubHref} className="inline-flex min-h-9 items-center gap-2 hover:text-foreground focus-visible:outline-2 focus-visible:outline-ring"><GitHubDark width={16} height={16} aria-hidden="true" />GitHub</a>}
      </div>
    </footer>
  );
}

export function Footer(props: FooterProps = {}) {
  return <FooterLayout {...props} layout="columns" />;
}

export function FooterMinimal(props: FooterProps = {}) {
  return <FooterLayout {...props} layout="minimal" />;
}

export function FooterStacked(props: FooterProps = {}) {
  return <FooterLayout {...props} layout="stacked" />;
}

import type { ComponentProps } from "react";

interface BadgeProps extends ComponentProps<"span"> {
  variant?: "neutral" | "info" | "success" | "warning" | "error" | "blue" | "purple" | "pink" | "teal" | "orange";
}

export function Badge({ children = "New release", variant = "success", className = "", ...props }: BadgeProps = {}) {
  const styles = {
    neutral: "bg-neutral-800 text-neutral-200",
    info: "bg-sky-400/10 text-sky-300",
    success: "bg-emerald-400/10 text-emerald-300",
    warning: "bg-amber-400/10 text-amber-300",
    error: "bg-red-400/10 text-red-300",
    blue: "bg-blue-400/10 text-blue-300",
    purple: "bg-purple-400/10 text-purple-300",
    pink: "bg-pink-400/10 text-pink-300",
    teal: "bg-teal-400/10 text-teal-300",
    orange: "bg-orange-400/10 text-orange-300",
  };
  return <span className={`inline-flex items-center border border-border px-2.5 py-1 text-xs font-medium ${styles[variant] ?? styles.success} ${className}`} {...props}>{children}</span>;
}

import type { ComponentProps, ReactNode } from "react";

interface CardProps extends Omit<ComponentProps<"article">, "title"> {
  title?: string;
  description?: string;
  footer?: ReactNode;
}

export function Card({ title = "Room for your next idea", description = "A simple starting point for something great. Make it yours.", children, footer, className = "", ...props }: CardProps = {}) {
  return <article className={`w-full max-w-sm border border-border bg-card p-6 text-card-foreground shadow-sm ${className}`} {...props}>
    {title && <h3 className="text-lg font-semibold">{title}</h3>}
    {description && <p className="mt-2 text-sm leading-6 opacity-80">{description}</p>}
    {children && <div className={title || description || footer ? "mt-5" : "h-full min-h-0"}>{children}</div>}
    {footer && <footer className="mt-5 border-t border-border pt-4">{footer}</footer>}
  </article>;
}
